def largest_sum_after_k_negations(nums, k):
    arr = nums[:]
    for _ in range(k):
        min_idx = 0
        for i in range(1, len(arr)):
            if arr[i] < arr[min_idx]:
                min_idx = i
        arr[min_idx] = -arr[min_idx]
    return sum(arr)


if __name__ == "__main__":
    print(largest_sum_after_k_negations([4, 2, 3], 1))
    print(largest_sum_after_k_negations([3, -1, 0, 2], 3))

