import java.util.*;

public class Main {
    static int largestSumAfterKNegations(int[] nums, int k) {
        int[] arr = nums.clone();
        Arrays.sort(arr);

        int i = 0;
        while (i < arr.length && k > 0 && arr[i] < 0) {
            arr[i] = -arr[i];
            i++;
            k--;
        }

        int total = 0, minVal = Integer.MAX_VALUE;
        for (int v : arr) {
            total += v;
            minVal = Math.min(minVal, v);
        }
        if (k % 2 == 1) {
            total -= 2 * minVal;
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println(largestSumAfterKNegations(new int[]{4, 2, 3}, 1));
        System.out.println(largestSumAfterKNegations(new int[]{3, -1, 0, 2}, 3));
    }
}

